import { z } from "zod";
import { orgIdSchema, webhookIdSchema } from "./common";

export const webhookEventTypeSchema = z.enum([
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "comment.created",
  "member.joined",
  "project.created",
  "project.archived",
  "billing.plan_changed",
]);

export const createWebhookSchema = z.object({
  orgId: orgIdSchema,
  url: z.url().max(2_000),
  eventTypes: z.array(webhookEventTypeSchema).min(1).max(20),
});

export const updateWebhookSchema = z.object({
  orgId: orgIdSchema,
  webhookId: webhookIdSchema,
  url: z.url().max(2_000).optional(),
  eventTypes: z.array(webhookEventTypeSchema).min(1).max(20).optional(),
  enabled: z.boolean().optional(),
});

export const deleteWebhookSchema = z.object({
  orgId: orgIdSchema,
  webhookId: webhookIdSchema,
});

/** Body accepted by the inbound webhook receiver route handler. */
export const inboundWebhookSchema = z.object({
  source: z.enum(["billing", "email", "ci"]),
  eventId: z.string().min(1).max(128),
  occurredAt: z.iso.datetime(),
  payload: z.record(z.string(), z.unknown()).default({}),
});

export type CreateWebhookInput = z.infer<typeof createWebhookSchema>;
export type UpdateWebhookInput = z.infer<typeof updateWebhookSchema>;
export type DeleteWebhookInput = z.infer<typeof deleteWebhookSchema>;
export type InboundWebhookInput = z.infer<typeof inboundWebhookSchema>;
--- member schema
import { z } from "zod";
import {
  emailSchema,
  memberIdSchema,
  orgIdSchema,
  pageRequestSchema,
  userIdSchema,
} from "./common";
import { invitableRoleSchema, memberStatusSchema, roleSchema } from "./role";

export const inviteMemberSchema = z.object({
  orgId: orgIdSchema,
  email: emailSchema,
  role: invitableRoleSchema.default("member"),
  message: z.string().max(500).optional(),
});

/** Bulk invite from the members settings page; the seat check runs once. */
export const inviteMembersSchema = z.object({
  orgId: orgIdSchema,
  invites: z
    .array(
      z.object({
        email: emailSchema,
        role: invitableRoleSchema.default("member"),
      }),
    )
    .min(1)
    .max(50),
});

export const acceptInvitationSchema = z.object({
  token: z.string().min(16),
});

export const revokeInvitationSchema = z.object({
  orgId: orgIdSchema,
  invitationId: z.string().min(1),
});

export const updateMemberRoleSchema = z.object({
  orgId: orgIdSchema,
  memberId: memberIdSchema,
  role: roleSchema,
});

export const removeMemberSchema = z.object({
  orgId: orgIdSchema,
  memberId: memberIdSchema,
});

export const listMembersSchema = z
  .object({
    orgId: orgIdSchema,
    role: roleSchema.optional(),
    status: memberStatusSchema.optional(),
    query: z.string().max(200).optional(),
  })
  .extend(pageRequestSchema.shape);

export const updateProfileSchema = z.object({
  userId: userIdSchema,
  name: z.string().min(1).max(80).optional(),
  avatarUrl: z.url().nullable().optional(),
  timezone: z.string().min(1).max(64).optional(),
});

export type InviteMemberInput = z.infer<typeof inviteMemberSchema>;
export type InviteMembersInput = z.infer<typeof inviteMembersSchema>;
export type UpdateMemberRoleInput = z.infer<typeof updateMemberRoleSchema>;
export type RemoveMemberInput = z.infer<typeof removeMemberSchema>;
export type ListMembersInput = z.infer<typeof listMembersSchema>;
export type UpdateProfileInput = z.infer<typeof updateProfileSchema>;
--- schemas index
/**
 * Barrel for the Zod contract. Client forms import the individual schema they
 * bind to a resolver; Server Actions import the same symbol. Never redeclare a
 * shape locally — extend the schema here instead.
 */
export * from "./common";
export * from "./slug";
export * from "./role";
export * from "./auth";
export * from "./session";
export * from "./organization";
export * from "./member";
export * from "./invitation";
export * from "./project";
export * from "./issue";
export * from "./comment";
export * from "./label";
export * from "./attachment";
export * from "./notification";
export * from "./activity";
export * from "./billing";
export * from "./feature-flag";
export * from "./search";
export * from "./webhook";
export * from "./export";
export * from "./pagination";
--- types index
/** Barrel for the Taskflow shared type contract. Prefer importing from the
 *  specific module (`@/types/issue`) in app code; this barrel exists for the
 *  handful of places that genuinely need many domains at once. */
export * from "./common";
export * from "./member";
export * from "./organization";
export * from "./project";
export * from "./issue";
export * from "./comment";
export * from "./notification";
export * from "./billing";
export * from "./activity";
export * from "./feature-flag";
export * from "./permission";
export * from "./event";
export * from "./api";

