): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  assertCan(actor, "api_token:create", apiTokenResource(actor.orgId, null, actor.userId));
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", apiTokenResource(actor.orgId, null, actor.userId));
  }

  const now = new Date();
  const token = `${TOKEN_PREFIX}${randomToken(SECRET_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: actor.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS_PER_USER,
  );

  if (apiToken === null) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS_PER_USER} active API tokens in this organization`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    ownerId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

/**
 * A user's tokens in the organization, newest first, revoked and expired
 * included. Anyone may list their own; another user's list needs `admin`.
 */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);

  const ownerId = userId ?? actor.userId;
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, null, ownerId));

  return apiTokenRepo.listApiTokensForUser(orgId, ownerId);
}

/**
 * Revokes a token. Revoking a token that is already revoked changes nothing
 * and records nothing: the original `revokedAt` is returned as it was.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const token = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );
  assertCan(actor, "api_token:manage", apiTokenResource(orgId, token.id, token.userId));

  const revoked = await apiTokenRepo.markApiTokenRevoked(
    orgId,
    token.id,
    toIsoTimestamp(new Date()),
  );
  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    ownerId: revoked.userId,
    name: revoked.name,
  });

  return revoked;
}

/**
 * Resolves a bearer token to the `Actor` it acts as, or `null` when it cannot
 * act: unknown, revoked, expired (from the instant of `expiresAt`), owned by a
 * user who is no longer an active member, or in a deleted organization.
 *
 * `read` tokens act as `viewer`. `write` tokens act with the owner's current
 * role, so promotions and demotions apply on the next call. Only a successful
 * call stamps `lastUsedAt`.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const now = new Date();

  const stored = await apiTokenRepo.findApiTokenByTokenHash(hashToken(token));
  if (stored === null) return null;
  if (stored.revokedAt !== null) return null;
  if (Date.parse(stored.expiresAt) <= now.getTime()) return null;

  const org = await orgRepo.findOrgById(stored.orgId);
  if (org === null || !isLive(org)) return null;

  const member = await resolveActor(stored.userId, stored.orgId);
  if (member === null) return null;

  await apiTokenRepo.touchApiTokenLastUsed(
    stored.orgId,
    stored.id,
    toIsoTimestamp(now),
  );

  return {
    userId: stored.userId,
    orgId: stored.orgId,
    role: stored.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Revokes a departing member's tokens in that organization, expired ones
 * included, audited with the remover as actor. Tokens revoked earlier keep
 * their stamp and are not audited again.
 */
export function registerApiTokenListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("member.removed", async (payload) => {
      const revoked = await apiTokenRepo.revokeApiTokensForUser(
        payload.orgId,
        payload.userId,
        toIsoTimestamp(new Date()),
      );

      for (const token of revoked) {
        await emit("api_token.revoked", {
          ...envelope(payload.orgId, payload.actorId),
          tokenId: token.id,
          ownerId: token.userId,
          name: token.name,
        });
      }
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

