import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { ZodError } from "zod";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as apiTokenService from "@/server/services/api-token-service";
import * as activityService from "@/server/services/activity-service";
import * as memberService from "@/server/services/member-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import { getDb, apiTokens } from "@/server/db";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  vi.useRealTimers();
  cleanup();
});

async function auditRows(actor: Tenant["actors"]["owner"], tenant: Tenant) {
  const page = await activityService.listActivity(actor, {
    orgId: tenant.org.id,
    action: ["api_token.created", "api_token.revoked"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("api tokens", () => {
  it("creates a read token; the secret is returned once and never stored", async () => {
    const t = await createTenant("tok1", "growth");
    const { token, apiToken } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id,
      name: "  CI  ",
      scope: "read",
      expiresInDays: 30,
    });
    expect(token.startsWith("tfk_")).toBe(true);
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(apiToken.name).toBe("CI");
    expect(apiToken.lastUsedAt).toBeNull();
    expect(apiToken.revokedAt).toBeNull();
    expect(Object.keys(apiToken)).not.toContain("tokenHash");
    expect(JSON.stringify(apiToken)).not.toContain(token);
    const expires = Date.parse(apiToken.expiresAt) - Date.parse(apiToken.createdAt);
    expect(expires).toBe(30 * 24 * 60 * 60 * 1000);

    const rows = getDb().select().from(apiTokens).all();
    expect(rows.some((r) => r.tokenHash === token)).toBe(false);
    expect(JSON.stringify(rows)).not.toContain(token);

    const audit = await auditRows(t.actors.owner, t);
    const created = audit.find((a) => a.subjectId === apiToken.id);
    expect(created).toMatchObject({ action: "api_token.created", subjectKind: "api_token", actorId: t.userIds.member });
    expect(JSON.stringify(audit)).not.toContain(token);
    expect(JSON.stringify(audit)).not.toContain(token.slice(12));
  });

  it("rejects invalid input with ZodError and stores nothing", async () => {
    const t = await createTenant("tok2", "growth");
    const bad = [
      { name: "   ", scope: "read", expiresInDays: 1 },
      { name: "x".repeat(81), scope: "read", expiresInDays: 1 },
      { name: "ok", scope: "admin", expiresInDays: 1 },
      { name: "ok", scope: "read", expiresInDays: 0 },
      { name: "ok", scope: "read", expiresInDays: 366 },
      { name: "ok", scope: "read", expiresInDays: 1.5 },
    ] as const;
    for (const b of bad) {
      await expect(
        apiTokenService.createApiToken(t.actors.owner, { orgId: t.org.id, ...b } as never),
      ).rejects.toBeInstanceOf(ZodError);
    }
    expect(await apiTokenService.listApiTokens(t.actors.owner, t.org.id)).toHaveLength(0);
  });

  it("enforces tenant scope and write-scope permissions", async () => {
    const t = await createTenant("tok3", "growth");
    const other = await createTenant("tok3b", "growth");
    await expect(
      apiTokenService.createApiToken(t.actors.owner, { orgId: other.org.id, name: "a", scope: "read", expiresInDays: 1 }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      apiTokenService.createApiToken(t.actors.viewer, { orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1 }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      apiTokenService.createApiToken(t.actors.viewer, { orgId: t.org.id, name: "r", scope: "read", expiresInDays: 1 }),
    ).resolves.toBeDefined();
    await expect(
      apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1 }),
    ).resolves.toBeDefined();
  });

  it("caps usable tokens at five per user, freeing a slot on revoke", async () => {
    const t = await createTenant("tok4", "growth");
    const made = [];
    for (let i = 0; i < 5; i++) {
      made.push(
        (await apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: `t${i}`, scope: "read", expiresInDays: 2 })).apiToken,
      );
    }
    await expect(
      apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: "six", scope: "read", expiresInDays: 2 }),
    ).rejects.toThrow();
    expect(await apiTokenService.listApiTokens(t.actors.member, t.org.id)).toHaveLength(5);

    // another user has their own allowance
    await expect(
      apiTokenService.createApiToken(t.actors.admin, { orgId: t.org.id, name: "a", scope: "read", expiresInDays: 2 }),
    ).resolves.toBeDefined();

    await apiTokenService.revokeApiToken(t.actors.member, t.org.id, made[0]!.id);
    await expect(
      apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: "six", scope: "read", expiresInDays: 2 }),
    ).resolves.toBeDefined();
  });

  it("lists own tokens; other users' lists need admin", async () => {
    const t = await createTenant("tok5", "growth");
    await apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: "m", scope: "read", expiresInDays: 2 });
    await expect(apiTokenService.listApiTokens(t.actors.member, t.org.id, t.userIds.admin)).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await apiTokenService.listApiTokens(t.actors.admin, t.org.id, t.userIds.member)).toHaveLength(1);
    await expect(apiTokenService.listApiTokens(t.actors.member, t.org.id, t.userIds.admin)).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("revokes: not-found, permission, idempotent", async () => {
    const t = await createTenant("tok6", "growth");
    const { apiToken } = await apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: "r", scope: "read", expiresInDays: 2 });
    await expect(apiTokenService.revokeApiToken(t.actors.member, t.org.id, "01HZZZZZZZZZZZZZZZZZZZZZZZ")).rejects.toMatchObject({ code: "not_found" });
    await expect(apiTokenService.revokeApiToken(t.actors.viewer, t.org.id, apiToken.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    const first = await apiTokenService.revokeApiToken(t.actors.admin, t.org.id, apiToken.id);
    expect(first.revokedAt).not.toBeNull();
    const again = await apiTokenService.revokeApiToken(t.actors.owner, t.org.id, apiToken.id);
    expect(again.revokedAt).toBe(first.revokedAt);
    const audit = (await auditRows(t.actors.owner, t)).filter((a) => a.action === "api_token.revoked" && a.subjectId === apiToken.id);
    expect(audit).toHaveLength(1);
    expect(audit[0]!.actorId).toBe(t.userIds.admin);
  });

  it("authenticates: scope→role, lastUsedAt, expiry boundary, revoked", async () => {
    vi.useFakeTimers({ now: new Date("2030-01-01T00:00:00.000Z"), toFake: ["Date"] });
    const t = await createTenant("tok7", "growth");
    const r = await apiTokenService.createApiToken(t.actors.owner, { orgId: t.org.id, name: "r", scope: "read", expiresInDays: 1 });
    const w = await apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1 });

    expect(await apiTokenService.authenticateApiToken(r.token)).toEqual({ userId: t.userIds.owner, orgId: t.org.id, role: "viewer" });
    expect(await apiTokenService.authenticateApiToken(w.token)).toEqual({ userId: t.userIds.member, orgId: t.org.id, role: "member" });
    expect(await apiTokenService.authenticateApiToken("tfk_nope")).toBeNull();

    const member = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId: member!.id, role: "admin" });
    expect((await apiTokenService.authenticateApiToken(w.token))?.role).toBe("admin");
    await memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId: member!.id, role: "member" });
    expect((await apiTokenService.authenticateApiToken(w.token))?.role).toBe("member");

    const stamped = await apiTokenRepo.findApiTokenById(t.org.id, w.apiToken.id);
    expect(stamped?.lastUsedAt).not.toBeNull();

    vi.setSystemTime(new Date(Date.parse(r.apiToken.expiresAt) - 1));
    expect(await apiTokenService.authenticateApiToken(r.token)).not.toBeNull();
    vi.setSystemTime(new Date(Date.parse(r.apiToken.expiresAt)));
    expect(await apiTokenService.authenticateApiToken(r.token)).toBeNull();
    vi.useRealTimers();

    await apiTokenService.revokeApiToken(t.actors.member, t.org.id, w.apiToken.id);
    expect(await apiTokenService.authenticateApiToken(w.token)).toBeNull();
  });

  it("removing a member revokes their tokens (including expired), audited with the remover", async () => {
    const t = await createTenant("tok8", "growth");
